using Microsoft.EntityFrameworkCore; using RoomBooking.Web.Contracts; using RoomBooking.Web.Data; using RoomBooking.Web.Models; using RoomBooking.Web.Services;
var builder=WebApplication.CreateBuilder(args); builder.Services.AddRazorComponents().AddInteractiveServerComponents(); builder.Services.AddDbContextFactory<RoomBookingDbContext>(o=>o.UseSqlite(builder.Configuration.GetConnectionString("RoomBooking")??"Data Source=roombooking.db")); builder.Services.AddScoped<BookingService>(); builder.Services.AddEndpointsApiExplorer(); builder.Services.AddSwaggerGen(); builder.Services.AddCors(o=>o.AddPolicy("Configured",p=>p.WithOrigins(builder.Configuration.GetSection("Cors:Origins").Get<string[]>()??[]).AllowAnyHeader().AllowAnyMethod()));
var app=builder.Build(); using(var scope=app.Services.CreateScope()) await DatabaseSeeder.SeedAsync(scope.ServiceProvider.GetRequiredService<IDbContextFactory<RoomBookingDbContext>>()); if(app.Environment.IsDevelopment()){app.UseSwagger();app.UseSwaggerUI();} app.UseStaticFiles(); app.UseCors("Configured"); app.UseAntiforgery();
app.MapGet("/api/rooms",async(bool? activeOnly,BookingService s)=>Results.Ok(await s.GetRoomsAsync(activeOnly==true))).WithName("GetRooms");
app.MapGet("/api/bookings",async(int? roomId,DateOnly? date,BookingStatus? status,BookingService s)=>Results.Ok(await s.GetBookingsAsync(roomId,date,status)));
app.MapGet("/api/bookings/{id:int}",async(int id,BookingService s)=>{var b=await s.GetAsync(id);return b is null?Results.Problem("Bokningen hittades inte.",statusCode:404):Results.Ok(b);});
app.MapPost("/api/bookings",async(BookingRequest r,BookingService s)=>{var x=await s.CreateAsync(r);if(x.Value is not null)return Results.Created($"/api/bookings/{x.Value.Id}",x.Value);return Results.Problem(x.Error,statusCode:x.Code);});
app.MapPut("/api/bookings/{id:int}",async(int id,BookingRequest r,BookingService s)=>{var x=await s.UpdateAsync(id,r);return x.Value is not null?Results.Ok(x.Value):Results.Problem(x.Error,statusCode:x.Code);});
app.MapPost("/api/bookings/{id:int}/cancel",async(int id,BookingService s)=>{var found=await s.GetAsync(id);if(found is null)return Results.Problem("Bokningen hittades inte.",statusCode:404);await s.CancelAsync(id);return Results.Ok(await s.GetAsync(id));});
app.MapRazorComponents<RoomBooking.Web.Components.App>().AddInteractiveServerRenderMode(); app.Run();
public partial class Program { }
